#!/usr/bin/env bash
# test_scripts.sh — scripts の回帰テスト (LLM 不要、一時 git リポで scaffold → gen → drift → verify skip を通す)。usage: test_scripts.sh
set -u
S="$(cd "$(dirname "$0")" && pwd)"
T="$(mktemp -d "${TMPDIR:-/tmp}/mid-harness-selftest.XXXXXX")"
trap 'rm -rf "$T"' EXIT
fail=0
ok() { echo "pass  $1"; }
ng() {
	echo "FAIL  $1"
	fail=1
}

git -C "$T" init -q
git -C "$T" config user.email t@t
git -C "$T" config user.name t
if python3 "$S/scaffold.py" "$T" >/dev/null; then ok "scaffold"; else ng "scaffold"; fi
if python3 "$S/scaffold.py" "$T" | grep -q "created (0)"; then ok "scaffold idempotent"; else ng "scaffold idempotent"; fi

# 既存 hooks.json に他人の handler を同居させておく
mkdir -p "$T/.codex"
printf '{"hooks":{"PreToolUse":[{"matcher":"Bash","hooks":[{"type":"command","command":"echo audit"}]}]},"other":1}\n' >"$T/.codex/hooks.json"
mkdir -p "$T/.claude"
printf '{"permissions":{"allow":["Bash(ls:*)"]}}\n' >"$T/.claude/settings.json"

if python3 "$S/gen_adapters.py" "$T" --quiet; then ok "gen"; else ng "gen"; fi
if grep -q '"echo audit"' "$T/.codex/hooks.json"; then ok "foreign handler kept"; else ng "foreign handler kept"; fi
if grep -q '"other": 1' "$T/.codex/hooks.json"; then ok "foreign key kept"; else ng "foreign key kept"; fi
if grep -q 'Bash(ls' "$T/.claude/settings.json"; then ok "permissions kept"; else ng "permissions kept"; fi
if grep -q 'git rev-parse --show-toplevel' "$T/.codex/hooks.json"; then ok "codex cmd resolves root"; else ng "codex cmd resolves root"; fi
if grep -q 'generated by mid-harness' "$T/.claude/agents/reviewer.md"; then ok "agent marker"; else ng "agent marker"; fi
if python3 "$S/gen_adapters.py" "$T" --quiet; then ok "gen idempotent"; else ng "gen idempotent"; fi
if grep -c '"echo audit"' "$T/.codex/hooks.json" | grep -q '^1$'; then ok "no duplicate on regen"; else ng "no duplicate on regen"; fi
if python3 "$S/check_drift.py" "$T" >/dev/null; then ok "no drift after gen"; else ng "no drift after gen"; fi

# 手書き agent 定義の保護
printf -- '---\nname: hand\ndescription: x\n---\nhand written\n' >"$T/.claude/agents/hand.md"
cp -R "$T/.agents/agent-specs/reviewer" "$T/.agents/agent-specs/hand"
printf 'skill_version: "t"\ntargets: [claude-code]\nskills_mode: manual\nagents: [reviewer, hand]\n' >"$T/.agents/harness.yaml"
if python3 "$S/gen_adapters.py" "$T" --quiet 2>/dev/null; then ng "handwritten agent protected"; else ok "handwritten agent protected"; fi
if grep -q 'hand written' "$T/.claude/agents/hand.md"; then ok "handwritten untouched (atomic)"; else ng "handwritten untouched (atomic)"; fi
if python3 "$S/gen_adapters.py" "$T" --quiet --adopt; then ok "adopt"; else ng "adopt"; fi

# TOML: backslash と """ を含む prompt
printf 'skill_version: "t"\ntargets: [codex]\nskills_mode: manual\nagents: [reviewer]\n' >"$T/.agents/harness.yaml"
printf 'Use C:\\new\\queue and literal """ here.\nline2 ends with quote "\n' >"$T/.agents/agent-specs/reviewer/prompt.md"
if python3 "$S/gen_adapters.py" "$T" --quiet --adopt; then ok "gen with backslash prompt"; else ng "gen with backslash prompt"; fi
if python3 -c "import importlib,importlib.util;tomllib=importlib.import_module('tomllib') if importlib.util.find_spec('tomllib') else importlib.import_module('tomli');d=tomllib.load(open('$T/.codex/agents/reviewer.toml','rb'));assert 'C:\\\\new\\\\queue' in d['developer_instructions'] and '\"\"\"' in d['developer_instructions']"; then ok "toml roundtrip"; else ng "toml roundtrip"; fi

# drift: generated skill dir に余剰ファイル
printf 'skill_version: "t"\ntargets: [claude-code]\nskills_mode: generate\nagents: []\n' >"$T/.agents/harness.yaml"
mkdir -p "$T/.agents/skills/demo"
printf -- '---\nname: demo\ndescription: d\n---\nx\n' >"$T/.agents/skills/demo/SKILL.md"
if python3 "$S/gen_adapters.py" "$T" --quiet --adopt; then ok "gen skills"; else ng "gen skills"; fi
if python3 "$S/check_drift.py" "$T" >/dev/null; then ok "no drift (skills)"; else ng "no drift (skills)"; fi
touch "$T/.claude/skills/demo/stale.txt"
if python3 "$S/check_drift.py" "$T" | grep -q "extra file"; then ok "drift detects extra file"; else ng "drift detects extra file"; fi
rm "$T/.claude/skills/demo/stale.txt"
rm "$T/.claude/skills/demo/.mid-harness-generated"
if python3 "$S/check_drift.py" "$T" >/dev/null 2>&1; then ng "drift detects marker loss"; else ok "drift detects marker loss (gen refuses unmarked dir)"; fi
rm -rf "$T/.claude/skills/demo" # マーカーを消した生成物を片付けて以降のテストに影響させない

# manifest validation
printf 'targets: [claude-code]\nhooks:\n  - event: pre-tool\n    script: scripts/agent-hooks/../../x.sh\n' >"$T/.agents/harness.yaml"
if python3 "$S/gen_adapters.py" "$T" --quiet 2>&1 | grep -q "symlink 越え不可"; then ok "reject path escape"; else ng "reject path escape"; fi
printf 'targets: [claude-code]\nagents: ["../x"]\n' >"$T/.agents/harness.yaml"
if python3 "$S/gen_adapters.py" "$T" --quiet 2>&1 | grep -q "名前のみ"; then ok "reject bad agent name"; else ng "reject bad agent name"; fi

# round2: orphan agent removal + empty codex block
printf 'skill_version: "t"\ntargets: [claude-code, codex]\nskills_mode: manual\nagents: [reviewer]\n' >"$T/.agents/harness.yaml"
printf 'Review carefully.\n' >"$T/.agents/agent-specs/reviewer/prompt.md"
python3 "$S/gen_adapters.py" "$T" --quiet --adopt || ng "gen reviewer"
printf -- '---\nname: keepme\ndescription: x\n---\nhand written keepme\n' >"$T/.claude/agents/keepme.md"
printf 'skill_version: "t"\ntargets: [claude-code, codex]\nskills_mode: manual\nagents: []\n' >"$T/.agents/harness.yaml"
if python3 "$S/gen_adapters.py" "$T" --quiet; then ok "gen with agents removed"; else ng "gen with agents removed"; fi
if [ ! -e "$T/.claude/agents/reviewer.md" ] && [ ! -e "$T/.codex/agents/reviewer.toml" ]; then ok "orphan agents removed"; else ng "orphan agents removed"; fi
if grep -q "mid-harness:begin" "$T/.codex/config.toml"; then ng "empty codex block removed"; else ok "empty codex block removed"; fi
if grep -q 'hand written keepme' "$T/.claude/agents/keepme.md" 2>/dev/null; then ok "handwritten agent not removed"; else ng "handwritten agent not removed"; fi
if python3 "$S/check_drift.py" "$T" >/dev/null; then ok "no drift after orphan removal"; else ng "no drift after orphan removal"; fi
# round2: exact owner tag (foreign handler that merely mentions the tag must survive)
printf 'skill_version: "t"\ntargets: [codex]\nskills_mode: manual\nhooks:\n  - event: pre-tool\n    matcher: Bash\n    script: scripts/agent-hooks/pre-tool-policy.sh\n' >"$T/.agents/harness.yaml"
printf '{"hooks":{"PreToolUse":[{"matcher":"Bash","hooks":[{"type":"command","command":"printf %%s # mid-harness release note"},{"type":"command","command":"bash scripts/agent-hooks/team-owned.sh"}]}]}}\n' >"$T/.codex/hooks.json"
if python3 "$S/gen_adapters.py" "$T" --quiet; then ok "gen exact tag"; else ng "gen exact tag"; fi
if grep -q "release note" "$T/.codex/hooks.json" && grep -q "team-owned.sh" "$T/.codex/hooks.json"; then ok "foreign handlers with lookalike text kept"; else ng "foreign handlers with lookalike text kept"; fi
# round2: agent marker must be at fixed position
printf -- '---\nname: hand2\ndescription: x\n---\nNotes about text generated by mid-harness from somewhere; do not edit\n' >"$T/.claude/agents/hand2.md"
cp -R "$T/.agents/agent-specs/reviewer" "$T/.agents/agent-specs/hand2"
printf 'skill_version: "t"\ntargets: [claude-code]\nskills_mode: manual\nagents: [hand2]\n' >"$T/.agents/harness.yaml"
if python3 "$S/gen_adapters.py" "$T" --quiet 2>/dev/null; then ng "lookalike marker not treated as owned"; else ok "lookalike marker not treated as owned"; fi
# round2: control chars in prompt
printf 'skill_version: "t"\ntargets: [codex]\nskills_mode: manual\nagents: [reviewer]\n' >"$T/.agents/harness.yaml"
printf 'has NUL \000 and CR \r here\n' >"$T/.agents/agent-specs/reviewer/prompt.md"
if python3 "$S/gen_adapters.py" "$T" --quiet --adopt; then ok "gen with control chars"; else ng "gen with control chars"; fi
# CR は Python の text mode (universal newlines) で LF に正規化される。NUL が round-trip すれば十分
if python3 -c "import importlib,importlib.util;tomllib=importlib.import_module('tomllib') if importlib.util.find_spec('tomllib') else importlib.import_module('tomli');d=tomllib.load(open('$T/.codex/agents/reviewer.toml','rb'));assert '\x00' in d['developer_instructions'], d"; then ok "control chars roundtrip"; else ng "control chars roundtrip"; fi
# round2: falsy manifest values rejected
printf 'targets: [codex]\nhooks: false\nagents: 0\n' >"$T/.agents/harness.yaml"
if python3 "$S/gen_adapters.py" "$T" --quiet 2>&1 | grep -q "はリスト"; then ok "falsy hooks/agents rejected"; else ng "falsy hooks/agents rejected"; fi
# round2: symlink inside core skill rejected
printf 'skill_version: "t"\ntargets: [claude-code]\nskills_mode: generate\n' >"$T/.agents/harness.yaml"
ln -s /etc/hosts "$T/.agents/skills/demo/outside.txt"
if python3 "$S/gen_adapters.py" "$T" --quiet 2>&1 | grep -q "symlink"; then ok "symlink in skill rejected"; else ng "symlink in skill rejected"; fi
rm "$T/.agents/skills/demo/outside.txt"
# round2: exec bit drift
mkdir -p "$T/.agents/skills/demo/scripts"
printf '#!/bin/sh\necho hi\n' >"$T/.agents/skills/demo/scripts/run.sh"
chmod 755 "$T/.agents/skills/demo/scripts/run.sh"
if python3 "$S/gen_adapters.py" "$T" --quiet && python3 "$S/check_drift.py" "$T" >/dev/null; then ok "no drift with exec script"; else ng "no drift with exec script"; fi
chmod 644 "$T/.claude/skills/demo/scripts/run.sh"
if python3 "$S/check_drift.py" "$T" | grep -q "exec bit differs"; then ok "drift detects exec bit"; else ng "drift detects exec bit"; fi
chmod 755 "$T/.claude/skills/demo/scripts/run.sh"
# round2: verify leaves no empty parent dir
rm -rf "$T/.claude/skills"
printf 'skill_version: "t"\ntargets: [claude-code]\nskills_mode: manual\n' >"$T/.agents/harness.yaml"
mkdir -p "$T/fakebin"
printf '#!/bin/sh\necho MID_HARNESS_PROBE_OK\n' >"$T/fakebin/claude"
chmod +x "$T/fakebin/claude"
if [ ! -e "$T/.claude/skills" ]; then ok "precondition: no .claude/skills"; else ng "precondition"; fi
PATH="$T/fakebin:$PATH" MID_HARNESS_VERIFY_TIMEOUT=20 bash "$S/verify.sh" "$T" >/dev/null 2>&1 # fake CLI: hook テストは fail するが cleanup を見る
if [ ! -e "$T/.claude/skills" ]; then ok "no empty parent left after probe cleanup"; else ng "no empty parent left after probe cleanup"; fi
if compgen -G "$T/.agents/skills/*probe*" >/dev/null; then ng "probe cleaned (fake cli)"; else ok "probe cleaned (fake cli)"; fi

# round3: front matter 無しの md の先頭 "# generated by mid-harness from" は手書き扱い (削除しない)
printf 'skill_version: "t"\ntargets: [claude-code, codex]\nskills_mode: manual\nagents: []\n' >"$T/.agents/harness.yaml"
printf '# generated by mid-harness from a design note; this is handwritten prose\nbody\n' >"$T/.claude/agents/prose.md"
printf -- '---\nname: x\n---\ntext\n---\n<!-- generated by mid-harness from x; do not edit -->\n' >"$T/.claude/agents/lateMarker.md"
if python3 "$S/gen_adapters.py" "$T" --quiet; then ok "gen (frontmatterless case)"; else ng "gen (frontmatterless case)"; fi
if [ -e "$T/.claude/agents/prose.md" ]; then ok "frontmatterless md not treated as owned"; else ng "frontmatterless md not treated as owned"; fi
if [ -e "$T/.claude/agents/lateMarker.md" ]; then ok "marker after second --- not treated as owned"; else ng "marker after second --- not treated as owned"; fi
# round3: 生成先が symlink なら失敗し、外部ファイルを書き換えない
OUTSIDE="$(mktemp)"
printf '{"sentinel":"outside"}\n' >"$OUTSIDE"
mv "$T/.claude/settings.json" "$T/.claude/settings.json.bak"
ln -s "$OUTSIDE" "$T/.claude/settings.json"
if python3 "$S/gen_adapters.py" "$T" --quiet 2>&1 | grep -q "symlink"; then ok "symlink target rejected"; else ng "symlink target rejected"; fi
if grep -q '"sentinel":"outside"' "$OUTSIDE"; then ok "outside file untouched"; else ng "outside file untouched"; fi
rm "$T/.claude/settings.json"
mv "$T/.claude/settings.json.bak" "$T/.claude/settings.json"
rm -f "$OUTSIDE"
# round3: codex を targets から外すと agent toml と管理ブロックが消え、hooks.json の所有 handler は残る
printf 'skill_version: "t"\ntargets: [claude-code, codex]\nskills_mode: manual\nhooks:\n  - event: pre-tool\n    matcher: Bash\n    script: scripts/agent-hooks/pre-tool-policy.sh\nagents: [reviewer]\n' >"$T/.agents/harness.yaml"
printf 'Review.\n' >"$T/.agents/agent-specs/reviewer/prompt.md"
python3 "$S/gen_adapters.py" "$T" --quiet --adopt || ng "gen both targets"
printf 'skill_version: "t"\ntargets: [claude-code]\nskills_mode: manual\nhooks:\n  - event: pre-tool\n    matcher: Bash\n    script: scripts/agent-hooks/pre-tool-policy.sh\nagents: [reviewer]\n' >"$T/.agents/harness.yaml"
if python3 "$S/gen_adapters.py" "$T" --quiet; then ok "gen after dropping codex"; else ng "gen after dropping codex"; fi
if [ ! -e "$T/.codex/agents/reviewer.toml" ]; then ok "codex agent removed on target drop"; else ng "codex agent removed on target drop"; fi
if grep -q "mid-harness:begin" "$T/.codex/config.toml"; then ng "codex block removed on target drop"; else ok "codex block removed on target drop"; fi
if grep -q "# mid-harness" "$T/.codex/hooks.json"; then ok "codex hook handler kept on target drop (documented asymmetry)"; else ng "codex hook handler kept on target drop"; fi
if python3 "$S/check_drift.py" "$T" >/dev/null; then ok "no drift after target drop"; else ng "no drift after target drop"; fi
# round3: core から skill を消すと生成 skill ディレクトリも消える
printf 'skill_version: "t"\ntargets: [claude-code]\nskills_mode: generate\nagents: []\n' >"$T/.agents/harness.yaml"
python3 "$S/gen_adapters.py" "$T" --quiet || ng "gen skills 2"
if [ -d "$T/.claude/skills/demo" ]; then ok "generated skill present"; else ng "generated skill present"; fi
rm -rf "$T/.agents/skills/demo"
if python3 "$S/gen_adapters.py" "$T" --quiet; then ok "gen after core skill removal"; else ng "gen after core skill removal"; fi
if [ ! -e "$T/.claude/skills/demo" ]; then ok "orphan generated skill removed"; else ng "orphan generated skill removed"; fi
if python3 "$S/check_drift.py" "$T" >/dev/null; then ok "no drift after skill removal"; else ng "no drift after skill removal"; fi

# 6 製品: 全 targets で生成 → drift ゼロ → 製品を外すと所有生成物だけ消える
printf 'skill_version: "t"\ntargets: [claude-code, codex, cursor, grok, copilot, antigravity]\nskills_mode: manual\nhooks:\n  - event: pre-tool\n    matcher: Bash\n    script: scripts/agent-hooks/pre-tool-policy.sh\nagents: [reviewer]\n' >"$T/.agents/harness.yaml"
printf 'Review.\n' >"$T/.agents/agent-specs/reviewer/prompt.md"
printf '{"other-hook":{"Stop":[{"hooks":[{"type":"command","command":"echo bye"}]}]}}\n' >"$T/.agents/hooks.json"
if python3 "$S/gen_adapters.py" "$T" --quiet --adopt; then ok "gen 6 targets"; else ng "gen 6 targets"; fi
for f in .cursor/hooks.json .cursor/agents/reviewer.md .grok/hooks/mid-harness.json .grok/agents/reviewer.md .github/hooks/mid-harness.json .github/agents/reviewer.md .agents/hooks.json .agents/agents/reviewer/agent.md; do
	if [ -f "$T/$f" ]; then ok "generated $f"; else ng "generated $f"; fi
done
if grep -q '"other-hook"' "$T/.agents/hooks.json" && grep -q '"mid-harness"' "$T/.agents/hooks.json"; then ok "antigravity: foreign named hook kept"; else ng "antigravity: foreign named hook kept"; fi
if grep -q 'beforeShellExecution' "$T/.cursor/hooks.json" && grep -q '"failClosed": true' "$T/.cursor/hooks.json"; then ok "cursor: event + failClosed"; else ng "cursor: event + failClosed"; fi
if grep -q 'readonly: true' "$T/.cursor/agents/reviewer.md"; then ok "cursor: readonly agent"; else ng "cursor: readonly agent"; fi
if grep -q 'permissionMode: plan' "$T/.grok/agents/reviewer.md"; then ok "grok: permissionMode plan"; else ng "grok: permissionMode plan"; fi
if python3 "$S/check_drift.py" "$T" >/dev/null; then ok "no drift (6 targets)"; else ng "no drift (6 targets)"; fi
printf 'skill_version: "t"\ntargets: [claude-code]\nskills_mode: manual\nhooks:\n  - event: pre-tool\n    matcher: Bash\n    script: scripts/agent-hooks/pre-tool-policy.sh\nagents: [reviewer]\n' >"$T/.agents/harness.yaml"
if python3 "$S/gen_adapters.py" "$T" --quiet; then ok "gen after dropping 5 targets"; else ng "gen after dropping 5 targets"; fi
for f in .cursor/agents/reviewer.md .grok/hooks/mid-harness.json .grok/agents/reviewer.md .github/hooks/mid-harness.json .github/agents/reviewer.md .agents/agents/reviewer/agent.md; do
	if [ ! -e "$T/$f" ]; then ok "removed $f"; else ng "removed $f"; fi
done
if grep -q 'other-hook' "$T/.agents/hooks.json"; then ok "antigravity: foreign hook kept after drop"; else ng "antigravity: foreign hook kept after drop"; fi
if python3 "$S/check_drift.py" "$T" >/dev/null; then ok "no drift after dropping 5 targets"; else ng "no drift after dropping 5 targets"; fi
# copilot: tools alias と matcher
printf 'skill_version: "t"\ntargets: [copilot]\nskills_mode: manual\nhooks:\n  - event: pre-tool\n    matcher: Bash\n    script: scripts/agent-hooks/pre-tool-policy.sh\nagents: [reviewer]\n' >"$T/.agents/harness.yaml"
if python3 "$S/gen_adapters.py" "$T" --quiet --adopt; then ok "gen copilot"; else ng "gen copilot"; fi
if grep -q 'tools: \[read, search\]' "$T/.github/agents/reviewer.md"; then ok "copilot: tools alias from policy"; else ng "copilot: tools alias from policy"; fi
if grep -q '"matcher": "bash|powershell"' "$T/.github/hooks/mid-harness.json"; then ok "copilot: matcher Bash -> bash|powershell"; else ng "copilot: matcher"; fi
# copilot / grok: 全 true → tools 省略、全 false → tools: []、model 指定
mkdir -p "$T/.agents/agent-specs/allt" "$T/.agents/agent-specs/nonet" "$T/.agents/agent-specs/modl"
printf 'p\n' | tee "$T/.agents/agent-specs/allt/prompt.md" "$T/.agents/agent-specs/nonet/prompt.md" "$T/.agents/agent-specs/modl/prompt.md" >/dev/null
printf 'description: d\ncapabilities: {read: true, edit: true, shell: true, delegate: true, network: true}\n' >"$T/.agents/agent-specs/allt/policy.yaml"
printf 'description: d\ncapabilities: {read: false, edit: false, shell: false, delegate: false, network: false}\non_unmappable: skip\n' >"$T/.agents/agent-specs/nonet/policy.yaml"
printf 'description: d\nmodel: gpt-5.6\ncapabilities: {read: true, edit: true, shell: true, delegate: true, network: true}\n' >"$T/.agents/agent-specs/modl/policy.yaml"
printf 'skill_version: "t"\ntargets: [copilot, grok]\nskills_mode: manual\nagents: [allt, nonet, modl]\n' >"$T/.agents/harness.yaml"
if python3 "$S/gen_adapters.py" "$T" --quiet --adopt; then ok "gen tools edge cases"; else ng "gen tools edge cases"; fi
if grep -q '^tools:' "$T/.github/agents/allt.md"; then ng "copilot: all true omits tools"; else ok "copilot: all true omits tools"; fi
if grep -q '^tools: \[\]$' "$T/.github/agents/nonet.md"; then ok "copilot: all false -> tools: []"; else ng "copilot: all false -> tools: []"; fi
if grep -q '^model: gpt-5.6$' "$T/.github/agents/modl.md"; then ok "copilot: model emitted"; else ng "copilot: model emitted"; fi
if grep -q '^tools:' "$T/.grok/agents/allt.md"; then ng "grok: all true omits tools"; else ok "grok: all true omits tools"; fi
if grep -q '^tools: \[\]$' "$T/.grok/agents/nonet.md"; then ok "grok: all false -> tools: []"; else ng "grok: all false -> tools: []"; fi
if python3 -c "import yaml,sys;t=open('$T/.grok/agents/nonet.md').read().split('---')[1];assert yaml.safe_load(t)['tools']==[]"; then ok "grok: tools: [] parses as empty list"; else ng "grok: tools: [] parses as empty list"; fi
# targets から外したのに所有 hook ファイル / キーが残っていたら drift として検出
printf 'skill_version: "t"\ntargets: [copilot, grok, antigravity]\nskills_mode: manual\nhooks:\n  - event: pre-tool\n    script: scripts/agent-hooks/pre-tool-policy.sh\n' >"$T/.agents/harness.yaml"
python3 "$S/gen_adapters.py" "$T" --quiet --adopt || ng "gen 3 targets for drift test"
printf 'skill_version: "t"\ntargets: [cursor]\nskills_mode: manual\nhooks:\n  - event: pre-tool\n    script: scripts/agent-hooks/pre-tool-policy.sh\n' >"$T/.agents/harness.yaml"
out="$(python3 "$S/check_drift.py" "$T" 2>&1)"
if printf '%s' "$out" | grep -q "orphan generated hook file: .grok" && printf '%s' "$out" | grep -q "orphan generated hook file: .github" && printf '%s' "$out" | grep -q "orphan generated hook key"; then ok "drift detects leftover owned hook files/keys after target drop"; else ng "drift detects leftover owned hook files/keys after target drop"; fi
if python3 "$S/gen_adapters.py" "$T" --quiet && python3 "$S/check_drift.py" "$T" >/dev/null; then ok "no drift after regenerating with dropped targets"; else ng "no drift after regenerating with dropped targets"; fi
# antigravity が targets 外で、手書きの同名キー 'mid-harness' があっても drift の孤児扱いにしない
printf 'skill_version: "t"\ntargets: [cursor]\nskills_mode: manual\n' >"$T/.agents/harness.yaml"
printf '{"mid-harness":{"Stop":[{"hooks":[{"command":"echo handwritten"}]}]}}\n' >"$T/.agents/hooks.json"
if python3 "$S/gen_adapters.py" "$T" --quiet && grep -q 'echo handwritten' "$T/.agents/hooks.json"; then ok "antigravity: handwritten key kept when not a target"; else ng "antigravity: handwritten key kept when not a target"; fi
if python3 "$S/check_drift.py" "$T" >/dev/null; then ok "drift: handwritten mid-harness key is not an orphan"; else ng "drift: handwritten mid-harness key is not an orphan"; fi
rm -f "$T/.agents/hooks.json"
# agy_project_id: folderUri 一致 / 複数 / 無し / 壊れたエントリ (HOME を差し替えてテスト)
FH="$(mktemp -d "${TMPDIR:-/tmp}/mh-fakehome.XXXXXX")"
mkdir -p "$FH/.gemini/config/projects"
printf '{"id":"p1","name":"x","projectResources":{"resources":[{"folderUri":"file:///repo/a"}]}}\n' >"$FH/.gemini/config/projects/1.json"
printf '{"id":"p2","name":"x","projectResources":{"resources":[{"folderUri":"file:///repo/a/"}]}}\n' >"$FH/.gemini/config/projects/2.json"
printf '{"id":"p3","name":"y","projectResources":{"resources":[{"folderUri":"file:///repo/b"}]}}\n' >"$FH/.gemini/config/projects/3.json"
if [ "$(HOME=$FH python3 "$S/agy_project_id.py" /repo/b)" = "p3" ]; then ok "agy_project_id: exact match"; else ng "agy_project_id: exact match"; fi
r="$(HOME=$FH python3 "$S/agy_project_id.py" /repo/a 2>"$FH/err")"
if [ "$r" = "p1" ] && grep -q "複数" "$FH/err"; then ok "agy_project_id: multiple -> first + warning"; else ng "agy_project_id: multiple -> first + warning"; fi
if [ -z "$(HOME=$FH python3 "$S/agy_project_id.py" /repo/none)" ]; then ok "agy_project_id: none -> empty"; else ng "agy_project_id: none -> empty"; fi
printf '{"id":{"unexpected":true},"projectResources":{"resources":[{"folderUri":"file:///repo/c"}]}}\n' >"$FH/.gemini/config/projects/4.json"
printf '{"id":"p5","projectResources":{"resources":[{"folderUri":["file:///repo/c"]}]}}\n' >"$FH/.gemini/config/projects/5.json"
printf 'not json\n' >"$FH/.gemini/config/projects/6.json"
printf '{"id":"p7","projectResources":{"resources":[{"folderUri":"file:///repo/c"}]}}\n' >"$FH/.gemini/config/projects/7.json"
if [ "$(HOME=$FH python3 "$S/agy_project_id.py" /repo/c 2>/dev/null)" = "p7" ]; then ok "agy_project_id: broken entries skipped, valid one found"; else ng "agy_project_id: broken entries skipped, valid one found"; fi
rm -rf "$FH"
# trust_status: HOME を差し替えて missing / ok / hooks 無し を検査
FH="$(mktemp -d "${TMPDIR:-/tmp}/mh-fakehome.XXXXXX")"
printf 'skill_version: "t"\ntargets: [claude-code, codex, grok, copilot, antigravity, cursor]\nskills_mode: manual\nhooks:\n  - event: pre-tool\n    script: scripts/agent-hooks/pre-tool-policy.sh\n' >"$T/.agents/harness.yaml"
HOME=$FH python3 "$S/trust_status.py" "$T" >"$FH/out" 2>&1
rc=$?
if [ "$rc" -eq 3 ] && grep -q "^codex *missing" "$FH/out" && grep -q "^copilot *missing" "$FH/out" && grep -q "^claude-code *-" "$FH/out"; then ok "trust_status: reports missing (exit 3)"; else ng "trust_status: reports missing (exit 3) rc=$rc"; fi
if grep -q "trustedFolders" "$FH/out" && grep -q "trusted_folders.toml" "$FH/out" && grep -q -- "--new-project" "$FH/out"; then ok "trust_status: how-to per product"; else ng "trust_status: how-to per product"; fi
TC="$(cd "$T" && git rev-parse --show-toplevel)" # trust は canonical パスで照合される
mkdir -p "$FH/.codex" "$FH/.grok" "$FH/.gemini/antigravity-cli" "$FH/.gemini/config/projects" "$FH/.copilot"
printf '[projects."%s"]\ntrust_level = "trusted"\n' "$TC" >"$FH/.codex/config.toml"
printf '[folders."%s"]\ntrusted = true\ndecided_at = 1\n' "$TC" >"$FH/.grok/trusted_folders.toml"
printf '{"trustedWorkspaces":["%s"]}\n' "$TC" >"$FH/.gemini/antigravity-cli/settings.json"
printf '{"id":"pX","projectResources":{"resources":[{"folderUri":"file://%s"}]}}\n' "$TC" >"$FH/.gemini/config/projects/x.json"
printf '{"trustedFolders":["%s"]}\n' "$TC" >"$FH/.copilot/settings.json"
if HOME=$FH python3 "$S/trust_status.py" "$T" >"$FH/out2" 2>&1 && grep -q "揃っています" "$FH/out2"; then ok "trust_status: all ok (exit 0)"; else ng "trust_status: all ok (exit 0)"; fi
printf 'skill_version: "t"\ntargets: [codex]\nskills_mode: manual\nhooks: []\n' >"$T/.agents/harness.yaml"
if HOME=$FH python3 "$S/trust_status.py" "$T" | grep -q "trust は不要"; then ok "trust_status: no hooks -> not needed"; else ng "trust_status: no hooks -> not needed"; fi
rm -rf "$FH"
# hooks: [] でも他人の hook ファイルは消さない (grok / copilot)、所有ファイルは消す
printf 'skill_version: "t"\ntargets: [grok, copilot]\nskills_mode: manual\nhooks: []\nagents: []\n' >"$T/.agents/harness.yaml"
mkdir -p "$T/.grok/hooks" "$T/.github/hooks"
printf '{"hooks":{"Stop":[]}}\n' >"$T/.grok/hooks/mid-harness.json"
if python3 "$S/gen_adapters.py" "$T" --quiet; then ok "gen hooks: [] (grok/copilot)"; else ng "gen hooks: [] (grok/copilot)"; fi
if [ -f "$T/.grok/hooks/mid-harness.json" ]; then ok "grok: foreign hook file kept on hooks: []"; else ng "grok: foreign hook file kept on hooks: []"; fi
if [ ! -e "$T/.github/hooks/mid-harness.json" ]; then ok "copilot: owned hook file removed on hooks: []"; else ng "copilot: owned hook file removed on hooks: []"; fi
rm -f "$T/.grok/hooks/mid-harness.json"
# antigravity: 手書きの同名キー 'mid-harness' は --adopt 無しで上書きしない
printf 'skill_version: "t"\ntargets: [antigravity]\nskills_mode: manual\nhooks:\n  - event: pre-tool\n    script: scripts/agent-hooks/pre-tool-policy.sh\n' >"$T/.agents/harness.yaml"
printf '{"mid-harness":{"Stop":[{"hooks":[{"type":"command","command":"echo handwritten"}]}]}}\n' >"$T/.agents/hooks.json"
if python3 "$S/gen_adapters.py" "$T" --quiet 2>&1 | grep -q "所有 ID 無し"; then ok "antigravity: foreign 'mid-harness' key protected"; else ng "antigravity: foreign 'mid-harness' key protected"; fi
if grep -q 'echo handwritten' "$T/.agents/hooks.json"; then ok "antigravity: handwritten key untouched"; else ng "antigravity: handwritten key untouched"; fi
if python3 "$S/gen_adapters.py" "$T" --quiet --adopt; then ok "antigravity: adopt"; else ng "antigravity: adopt"; fi
printf 'skill_version: "t"\ntargets: [claude-code]\nskills_mode: manual\n' >"$T/.agents/harness.yaml"
if python3 "$S/gen_adapters.py" "$T" --quiet; then ok "gen drop antigravity"; else ng "gen drop antigravity"; fi
if grep -q '"mid-harness"' "$T/.agents/hooks.json"; then ng "antigravity: owned key removed on target drop"; else ok "antigravity: owned key removed on target drop"; fi
# grok の hook ファイルが他人のものなら上書きしない
printf 'skill_version: "t"\ntargets: [grok]\nskills_mode: manual\nhooks:\n  - event: pre-tool\n    script: scripts/agent-hooks/pre-tool-policy.sh\n' >"$T/.agents/harness.yaml"
mkdir -p "$T/.grok/hooks"
printf '{"hooks":{"Stop":[]}}\n' >"$T/.grok/hooks/mid-harness.json"
if python3 "$S/gen_adapters.py" "$T" --quiet 2>&1 | grep -q "所有マーカー無し"; then ok "grok: foreign hook file protected"; else ng "grok: foreign hook file protected"; fi
rm -f "$T/.grok/hooks/mid-harness.json"

# verify skip-llm with probe cleanup, and refuse to clobber existing probe-like dirs (名前が一意なので衝突しない)
printf 'skill_version: "t"\ntargets: [claude-code, codex]\nskills_mode: manual\n' >"$T/.agents/harness.yaml"
if MID_HARNESS_VERIFY_SKIP_LLM=1 bash "$S/verify.sh" "$T" >/dev/null; then ok "verify skip"; else ng "verify skip"; fi
if compgen -G "$T/.agents/skills/*probe*" >/dev/null; then ng "probe cleaned"; else ok "probe cleaned"; fi

exit "$fail"
